import threading, json, urllib.request

def run(**kwargs):
    url = kwargs.get("url")
    body = kwargs.get("body", "")
    headers = kwargs.get("headers") or {}
    n = int(kwargs.get("n", 20))
    rounds = int(kwargs.get("rounds", 2))
    all_rounds = []
    for rnd in range(rounds):
        outcomes = []
        lock = threading.Lock()
        barrier = threading.Barrier(n)
        def fire(i):
            try:
                barrier.wait(timeout=15)
                req = urllib.request.Request(url, data=body.encode(), method="POST")
                for k, v in headers.items():
                    req.add_header(k, v)
                with urllib.request.urlopen(req, timeout=20) as r:
                    txt = r.read(300).decode(errors="replace")
                    with lock:
                        outcomes.append((r.status, txt[:200]))
            except Exception as e:
                with lock:
                    outcomes.append(("ERR", str(e)[:150]))
        ts = [threading.Thread(target=fire, args=(i,)) for i in range(n)]
        for t in ts:
            t.start()
        for t in ts:
            t.join(40)
        all_rounds.append(outcomes)
    uniq = {}
    for r_ in all_rounds:
        for o in r_:
            key = str(o[0]) + " | " + o[1][:100]
            uniq[key] = uniq.get(key, 0) + 1
    return json.dumps({"rounds": len(all_rounds), "total_requests": sum(len(r_) for r_ in all_rounds), "outcome_histogram": uniq}, indent=1)

